            className={`px-4 py-2 text-sm font-medium rounded-lg whitespace-nowrap transition-colors ${
              activeCategory === category
                ? 'bg-[#3861FB] text-white'
                : 'text-[#808A9D] hover:text-[#0D1421] hover:bg-[#f8f9fb]'
            }`}
          >
            {category}
          </button>
        ))}
      </div>
    </div>
  )
}

