  const SortIcon = ({ column }: { column: SortKey }) => {
    if (sortKey !== column) return <span className="text-[#c4c9d4] ml-1">↕</span>
    return <span className="text-[#3861FB] ml-1">{sortOrder === 'asc' ? '↑' : '↓'}</span>
