                      onChange={() => toggleColumn(col as keyof typeof visibleColumns)}
                      className="w-4 h-4 rounded border-[#e5e7eb] text-[#3861FB] focus:ring-[#3861FB]"
                    />
                    <span className="text-sm text-[#0D1421] capitalize">{col}</span>
