arguments.content:
@import "tailwindcss";

@theme {
  --color-brand-blue: #3861FB;
  --color-brand-blue-hover: #2d4edb;
  --color-dark-navy: #0D1421;
  --color-secondary-gray: #808A9D;
  --color-positive: #16c784;
  --color-negative: #ea3943;
  --color-warning: #f59e0b;
  --color-surface: #f8f9fb;
  --color-border: #e5e7eb;
}

@layer base {
  * {
    box-sizing: border-box;
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
